// Golden XML byte-parity gate — the Go xml package MUST reproduce every
// TS-frozen fixture byte-exactly (unsigned UBL 2.1 documents + canonical form
// + invoice hash). Fixtures are generated by
// apps/api/scripts/zatca-golden-vectors.ts into testdata/xml/.
//
// Regenerate with: pnpm --filter api exec tsx scripts/zatca-golden-vectors.ts
package xml_test

import (
	"encoding/json"
	"os"
	"testing"
	"time"

	xml "github.com/talha7k/zatca-go/xml"
)

// ---------------------------------------------------------------------------
// Manifest decoding — TS InvoiceData JSON → Go types. Decimal fields accept
// both JSON numbers and strings (the TS DecimalInput union).
// ---------------------------------------------------------------------------

type manifestFixture struct {
	ID                string          `json:"id"`
	DocumentKind      string          `json:"document_kind"`
	RawInvoiceData    json.RawMessage `json:"invoice_data"`
	XML               string          `json:"xml"`
	Canonical         string          `json:"canonical"`
	InvoiceHashHex    string          `json:"invoice_hash_hex"`
	InvoiceHashBase64 string          `json:"invoice_hash_base64"`
}

type manifest struct {
	Meta struct {
		Generator string `json:"generator"`
	} `json:"_meta"`
	Fixtures []manifestFixture `json:"fixtures"`
}

func loadXMLManifest(t *testing.T) manifest {
	t.Helper()
	raw, err := os.ReadFile("../testdata/xml/manifest.json")
	if err != nil {
		t.Fatalf("read xml manifest: %v", err)
	}
	var m manifest
	if err := json.Unmarshal(raw, &m); err != nil {
		t.Fatalf("parse xml manifest: %v", err)
	}
	if len(m.Fixtures) < 4 {
		t.Fatalf("expected at least 4 xml fixtures, got %d", len(m.Fixtures))
	}
	return m
}

func decodeFixtureData(t *testing.T, fixture manifestFixture) (invoice *xml.InvoiceData, creditNote *xml.CreditNoteData) {
	t.Helper()
	// Decode the common invoice shape first, then re-decode the note fields
	// for credit notes.
	if err := json.Unmarshal(fixture.RawInvoiceData, &invoice); err != nil {
		t.Fatalf("%s: decode invoice_data: %v", fixture.ID, err)
	}
	if fixture.DocumentKind == "credit_note" {
		if err := json.Unmarshal(fixture.RawInvoiceData, &creditNote); err != nil {
			t.Fatalf("%s: decode credit note data: %v", fixture.ID, err)
		}
		// Go zero values differ from JSON absence — the TS originalInvoice*
		// fields are strings on the fixture; keep whatever decoded.
	}
	return invoice, creditNote
}

// TestGoldenXMLByteParity: for every fixture, the Go builder must emit the
// exact TS XML bytes, and the hash over the TS canonical form must equal the
// frozen digest.
func TestGoldenXMLByteParity(t *testing.T) {
	m := loadXMLManifest(t)
	seen := map[string]bool{}
	for _, fixture := range m.Fixtures {
		t.Run(fixture.ID, func(t *testing.T) {
			if seen[fixture.ID] {
				t.Fatalf("duplicate fixture id %s", fixture.ID)
			}
			seen[fixture.ID] = true
			invoice, creditNote := decodeFixtureData(t, fixture)

			// The .xml fixture file on disk must match the manifest copy.
			diskXML, err := os.ReadFile("../testdata/xml/" + fixture.ID + ".xml")
			if err != nil {
				t.Fatalf("read fixture xml: %v", err)
			}
			if string(diskXML) != fixture.XML {
				t.Fatalf("%s.xml on disk diverges from the manifest", fixture.ID)
			}

			var got string
			switch fixture.DocumentKind {
			case "invoice":
				got, err = xml.GenerateInvoiceXml(invoice)
			case "credit_note":
				got, err = xml.GenerateCreditNoteXml(creditNote)
			default:
				t.Fatalf("unknown document_kind %q", fixture.DocumentKind)
			}
			if err != nil {
				t.Fatalf("generate: %v", err)
			}
			if got != fixture.XML {
				t.Errorf("XML bytes diverge from the TS fixture\n--- got ---\n%s\n--- want ---\n%s", got, fixture.XML)
			}

			// Canonical hash parity (hashing is ours; canonicalization stays TS).
			diskCanonical, err := os.ReadFile("../testdata/xml/" + fixture.ID + ".canonical.xml")
			if err != nil {
				t.Fatalf("read fixture canonical: %v", err)
			}
			if string(diskCanonical) != fixture.Canonical {
				t.Fatalf("%s.canonical.xml on disk diverges from the manifest", fixture.ID)
			}
			hash := xml.HashCanonical(fixture.Canonical).Base64
			if hash != fixture.InvoiceHashBase64 {
				t.Errorf("invoice_hash mismatch:\n got  %s\n want %s", hash, fixture.InvoiceHashBase64)
			}
			if fixture.InvoiceHashHex == "" || len(fixture.InvoiceHashHex) != 64 {
				t.Errorf("invoice_hash_hex must be a 64-char digest, got %d chars", len(fixture.InvoiceHashHex))
			}
		})
	}
	// Coverage: the three required document types must all be present.
	for _, want := range []string{"standard-b2b-vat15", "simplified-b2c-multiline-vat15", "credit-note-simplified-vat15"} {
		if !seen[want] {
			t.Errorf("missing required fixture %q", want)
		}
	}
}

// TestPatchInvoiceChainReferences pins the ICV/PIH patching discipline on the
// frozen fixture bytes.
func TestPatchInvoiceChainReferences(t *testing.T) {
	m := loadXMLManifest(t)
	var fixture *manifestFixture
	for i := range m.Fixtures {
		if m.Fixtures[i].ID == "standard-b2b-vat15" {
			fixture = &m.Fixtures[i]
		}
	}
	if fixture == nil {
		t.Fatal("standard fixture missing")
	}

	// Rewrite the chain on the frozen XML: ICV=7, PIH=custom.
	customPIH := "QUJDREVGR0hJSktMTU5PUFFSU1RVVldYWVphYmNkZWY=" // 32 bytes base64
	patched := xml.PatchInvoiceChainReferences(fixture.XML, customPIH, 7)
	if !contains(patched, "<cbc:UUID>7</cbc:UUID>") {
		t.Error("ICV counter not patched to 7")
	}
	if !contains(patched, `<cbc:EmbeddedDocumentBinaryObject mimeCode="text/plain">`+customPIH+`</cbc:EmbeddedDocumentBinaryObject>`) {
		t.Error("PIH not patched to the custom hash")
	}
	// Exactly one ICV and one PIH reference must remain.
	for _, id := range []string{"ICV", "PIH"} {
		if got := countOccurrences(patched, "<cbc:ID>"+id+"</cbc:ID>"); got != 1 {
			t.Errorf("reference %s appears %d times, want 1", id, got)
		}
	}

	// Empty previous hash falls back to the genesis PIH.
	patchedGenesis := xml.PatchInvoiceChainReferences(fixture.XML, "", 2)
	if !contains(patchedGenesis, xml.GenesisPIH) {
		t.Error("genesis PIH fallback missing")
	}
}

func TestPatchProductionXML(t *testing.T) {
	xmlString := `<?xml version="1.0" encoding="UTF-8"?>
<Invoice xmlns="urn:oasis:names:specification:ubl:schema:xsd:Invoice-2">
  <cbc:ProfileID>clearance:1.0</cbc:ProfileID>
  <cbc:InvoiceTypeCode name="0100000">388</cbc:InvoiceTypeCode>
  <cbc:IssueDate>2026-10-06</cbc:IssueDate>
  <cac:TaxTotal>
    <cbc:TaxAmount currencyID="SAR">15.00</cbc:TaxAmount>
  </cac:TaxTotal>
</Invoice>`
	patched := xml.PatchProductionXML(xmlString)
	if !contains(patched, "<cbc:ProfileID>reporting:1.0</cbc:ProfileID>") {
		t.Error("profile not patched to reporting:1.0")
	}
	if !contains(patched, "<cac:Delivery>\n    <cbc:ActualDeliveryDate>2026-10-06</cbc:ActualDeliveryDate>") {
		t.Errorf("supply date not inserted before TaxTotal:\n%s", patched)
	}
	// A document that already carries Delivery must be left untouched.
	again := xml.PatchStandardInvoiceSupplyDate(patched)
	if again != patched {
		t.Error("patched document must be idempotent")
	}
}

func TestPatchSimplifiedCreditDebitCustomerParty(t *testing.T) {
	simplified := `<cbc:InvoiceTypeCode name="0200000">381</cbc:InvoiceTypeCode>
  <cac:PaymentMeans>
    <cbc:PaymentMeansCode>10</cbc:PaymentMeansCode>
  </cac:PaymentMeans>`
	patched := xml.PatchSimplifiedCreditDebitCustomerParty(simplified)
	if !contains(patched, "<cac:AccountingCustomerParty>\n  </cac:AccountingCustomerParty>") {
		t.Errorf("empty customer party not inserted:\n%s", patched)
	}
	// Documents with a customer party and standard invoices stay untouched.
	if got := xml.PatchSimplifiedCreditDebitCustomerParty(patched); got != patched {
		t.Error("patch must be idempotent")
	}
	if got := xml.PatchSimplifiedCreditDebitCustomerParty(`<cbc:InvoiceTypeCode name="0100000">388</cbc:InvoiceTypeCode>`); got != `<cbc:InvoiceTypeCode name="0100000">388</cbc:InvoiceTypeCode>` {
		t.Error("standard invoices must not be patched")
	}
}

// ---------------------------------------------------------------------------
// Mapping discipline — integer-cents inclusive VAT (BR-CO-17)
// ---------------------------------------------------------------------------

func TestVATFromInclusiveCents(t *testing.T) {
	cases := []struct {
		name        string
		grossCents  int64
		rate        float64
		wantTaxable int64
		wantTax     int64
		wantTotal   int64
	}{
		{"TS doc example 10.00@15%", 1000, 15, 870, 131, 1001},
		{"115.00@15%", 11500, 15, 10000, 1500, 11500},
		{"175.00@15% penny drift", 17500, 15, 15217, 2283, 17500},
		{"zero rate", 5000, 0, 5000, 0, 5000},
		{"5% rate", 10500, 5, 10000, 500, 10500},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			taxable, tax, total := xml.VATFromInclusiveCents(tc.grossCents, tc.rate)
			if taxable != tc.wantTaxable || tax != tc.wantTax || total != tc.wantTotal {
				t.Errorf("got taxable=%d tax=%d total=%d, want %d/%d/%d",
					taxable, tax, total, tc.wantTaxable, tc.wantTax, tc.wantTotal)
			}
		})
	}
}

func TestNormalizeNumbers(t *testing.T) {
	if got := xml.NormalizeBuildingNumber("٣٤٥"); got != "0345" { // Arabic-Indic 345
		t.Errorf("NormalizeBuildingNumber arabic: got %q", got)
	}
	if got := xml.NormalizeBuildingNumber("12345"); got != "2345" {
		t.Errorf("NormalizeBuildingNumber slice: got %q", got)
	}
	if got := xml.NormalizeBuildingNumber("no-digits!"); got != "no-digits!" {
		t.Errorf("NormalizeBuildingNumber passthrough: got %q", got)
	}
	if got := xml.NormalizePostalCode("١٢٣٤"); got != "01234" {
		t.Errorf("NormalizePostalCode arabic: got %q", got)
	}
}

func TestIssueDateNotAfterToday(t *testing.T) {
	now := timeUTC(2026, 10, 6)
	if got := xml.IssueDateNotAfterToday(timeUTC(2026, 10, 7), now); got != "2026-10-06" {
		t.Errorf("future date must clamp to today, got %q", got)
	}
	if got := xml.IssueDateNotAfterToday(timeUTC(2026, 10, 5), now); got != "2026-10-05" {
		t.Errorf("past date must be kept, got %q", got)
	}
	if got := xml.IssueDateNotAfterToday(timeUTC(2026, 10, 6), now); got != "2026-10-06" {
		t.Errorf("today must be kept, got %q", got)
	}
}

// ---------------------------------------------------------------------------
// Decimal formatting — exact HALF-UP semantics
// ---------------------------------------------------------------------------

func TestFormatAmount(t *testing.T) {
	cases := []struct {
		in   xml.Decimal
		want string
	}{
		{"115.00", "115.00"},
		{"2.675", "2.68"}, // float path would give 2.67 — HALF-UP is exact
		{"-0.00", "0.00"},
		{"0.005", "0.01"},
		{"7.5", "7.50"},
		{"100", "100.00"},
	}
	for _, tc := range cases {
		got, err := xml.FormatAmount(tc.in)
		if err != nil {
			t.Fatalf("FormatAmount(%q): %v", tc.in, err)
		}
		if got != tc.want {
			t.Errorf("FormatAmount(%q) = %q, want %q", tc.in, got, tc.want)
		}
	}
	if _, err := xml.FormatAmount("abc"); err == nil {
		t.Error("non-decimal input must error")
	}
}

func TestFormatUnitPrice(t *testing.T) {
	cases := []struct {
		in   xml.Decimal
		want string
	}{
		{"2", "2.00"},
		{"250.00", "250.00"},
		{"10.5", "10.50"},
		{"0.12345678901", "0.123456789"}, // 10dp cap HALF-UP then trailing-zero trim (TS parity)
		{"1.0000000000001", "1.00"},
	}
	for _, tc := range cases {
		got, err := xml.FormatUnitPrice(tc.in)
		if err != nil {
			t.Fatalf("FormatUnitPrice(%q): %v", tc.in, err)
		}
		if got != tc.want {
			t.Errorf("FormatUnitPrice(%q) = %q, want %q", tc.in, got, tc.want)
		}
	}
}

func TestAddDecimal(t *testing.T) {
	got, err := xml.AddDecimal("100.00", "15.00")
	if err != nil || got != "115.00" {
		t.Errorf("AddDecimal 100.00+15.00 = %q err=%v", got, err)
	}
	got, err = xml.AddDecimal("0.1", "0.2")
	if err != nil || got != "0.3" {
		t.Errorf("AddDecimal 0.1+0.2 = %q err=%v (floats forbidden)", got, err)
	}
	got, err = xml.AddDecimal("-5.50", "2.25")
	if err != nil || got != "-3.25" {
		t.Errorf("AddDecimal -5.50+2.25 = %q err=%v", got, err)
	}
}

func TestFormatPercentFixed2(t *testing.T) {
	cases := []struct {
		in   float64
		want string
	}{
		{15, "15.00"},
		{0, "0.00"},
		{5, "5.00"},
		{14.5, "14.50"},
	}
	for _, tc := range cases {
		got, err := xml.FormatPercentFixed2(tc.in)
		if err != nil {
			t.Fatalf("FormatPercentFixed2(%v): %v", tc.in, err)
		}
		if got != tc.want {
			t.Errorf("FormatPercentFixed2(%v) = %q, want %q", tc.in, got, tc.want)
		}
	}
}

func TestEscapeXML(t *testing.T) {
	got := xml.EscapeXML(`مطعم & "الوادي" <الهندي> 'test'`)
	want := "مطعم &amp; &quot;الوادي&quot; &lt;الهندي&gt; &apos;test&apos;"
	if got != want {
		t.Errorf("EscapeXML = %q, want %q", got, want)
	}
}

func TestGenerateDebitNoteRejectsWrongCode(t *testing.T) {
	_, err := xml.GenerateDebitNoteXml(&xml.CreditNoteData{InvoiceData: xml.InvoiceData{InvoiceTypeCode: "381"}})
	if err == nil {
		t.Error("debit note with type 381 must be rejected")
	}
}

func TestGenerateInvalidDecimalErrors(t *testing.T) {
	inv := validGoInvoice(t)
	inv.LineExtensionAmount = "not-a-number"
	if _, err := xml.GenerateInvoiceXml(inv); err == nil {
		t.Error("invalid decimal must surface as a generation error")
	}
}

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

func contains(s, sub string) bool {
	return len(s) >= len(sub) && (func() bool {
		for i := 0; i+len(sub) <= len(s); i++ {
			if s[i:i+len(sub)] == sub {
				return true
			}
		}
		return false
	})()
}

func countOccurrences(s, sub string) int {
	count := 0
	for i := 0; i+len(sub) <= len(s); i++ {
		if s[i:i+len(sub)] == sub {
			count++
		}
	}
	return count
}

func timeUTC(y int, m int, d int) time.Time {
	return time.Date(y, time.Month(m), d, 12, 0, 0, 0, time.UTC)
}

// validGoInvoice builds a minimal well-formed invoice for error-path tests.
func validGoInvoice(t *testing.T) *xml.InvoiceData {
	t.Helper()
	counter := 1
	allowanceZero := xml.Decimal("0.00")
	fifteen := 15.0
	return &xml.InvoiceData{
		InvoiceNumber:       "INV-1",
		UUID:                "uuid-1",
		IssueDate:           "2026-10-06",
		IssueTime:           "10:00:00",
		InvoiceTypeCode:     "388",
		InvoiceTypeCodeName: "0100000",
		ProfileID:           "reporting:1.0",
		CurrencyCode:        "SAR",
		InvoiceCounter:      &counter,
		PreviousInvoiceHash: xml.GenesisPIH,
		Supplier: xml.SupplierInfo{
			NameAr:    "مطعم",
			VATNumber: "310122393500003",
			Address: xml.PostalAddress{
				Street: "King Fahd Road", Building: "1234", AdditionalNumber: "5678",
				District: "Al Olaya", City: "Riyadh", PostalCode: "12211", CountryCode: "SA",
			},
		},
		LineExtensionAmount: "100.00",
		TaxExclusiveAmount:  "100.00",
		TaxInclusiveAmount:  "115.00",
		PayableAmount:       "115.00",
		TaxAmount:           "15.00",
		TaxSubtotals: []xml.TaxSubtotal{
			{TaxableAmount: "100.00", TaxAmount: "15.00", Percent: fifteen, TaxCategoryID: "S"},
		},
		InvoiceLines: []xml.InvoiceLineItem{
			{ID: 1, Quantity: "1", UnitCode: "PCE", LineExtensionAmount: "100.00", TaxAmount: "15.00",
				ItemName: "Test", TaxCategoryID: "S", TaxPercent: fifteen, PriceAmount: "100.00"},
		},
		AllowanceTotalAmount: &allowanceZero,
	}
}
